82	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
83	{
84	    for (guint i = 0; i < regs->len; i++) {
85	        qemu_plugin_reg_descriptor *rd =
86	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
87	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
88	            return rd->handle;
89	        }
90	    }
91	    return NULL;
92	}
