371	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
372	                                           const qemu_info_t *info,
373	                                           int argc, char **argv)
374	{
375	    (void) info;
376	    for (int i = 0; i < argc; i++) {
377	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
378	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
379	            outfile_path = g_strdup(tok[1]);
380	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
381	            char *endp = NULL;
382	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
383	            if (!endp || *endp != '\0') {
384	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
385	                        tok[1]);
386	                return -1;
387	            }
388	            enter_pc_arg = (uint64_t) v;
389	            pc_mode = 1;
390	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
391	            // F14: any non-zero value enables. "1" is the canonical form
392	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
393	            // also enable -- the flag is a binary switch, not a count.
394	            char *endp = NULL;
395	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
396	            if (!endp || *endp != '\0') {
397	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
398	                        tok[1]);
399	                return -1;
400	            }
401	            drain_at_exit_mode = (v != 0);
402	        } else {
403	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
404	            return -1;
405	        }
406	    }
407	    if (!outfile_path) {
408	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
409	        return -1;
410	    }
411	    if (pc_mode) {
412	        fprintf(stderr,
413	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
414	                enter_pc_arg);
415	    }
416	    if (drain_at_exit_mode) {
417	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
418	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
419	    }
420	
421	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
422	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
423	    return 0;
424	}
